            identity = record["identity"]
            if identity not in grouped:
                grouped[identity] = {
                    "cutoffs": set(),
                    "hit": 0,
                    "missed": 0,
                    "unresolved": 0,
                    "unexpected": 0,
                    "first_failure": None,
                }
                order.append(identity)
            entry = grouped[identity]
            entry["cutoffs"].add(record["cutoff"])
            for key in ("hit", "missed", "unresolved", "unexpected"):
                entry[key] += record[key]
            if record["missed"] > 0 or record["unexpected"] > 0:
                if (
                    entry["first_failure"] is None
                    or record["cutoff"] < entry["first_failure"]
                ):
                    entry["first_failure"] = record["cutoff"]
        expected = {}
        for identity in order:
            entry = grouped[identity]
            evaluated = entry["hit"] + entry["missed"]
