                divisor = math.gcd(entry["hit"], evaluated)
                hit_rate = (entry["hit"] // divisor, evaluated // divisor)
            expected[identity] = (
                identity,
                len(entry["cutoffs"]),
                entry["hit"],
                entry["missed"],
                entry["unresolved"],
                entry["unexpected"],
                evaluated,
                hit_rate,
                entry["first_failure"],
